import re
import sys

def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    old_limit = sys.getrecursionlimit()
    if old_limit < 20000:
        sys.setrecursionlimit(20000)

    token_re = re.compile(r'\s*(?:(\d+)|([A-Z]\d+|[A-Z]+)|(<>|<=|>=|[=<>+\-*/(),:]))')

    def tokenize(s: str):
        tokens = []
        pos = 0
        n = len(s)
        while pos < n:
            if s[pos].isspace():
                pos += 1
                continue
            m = token_re.match(s, pos)
            if not m:
                raise ValueError(f"Invalid token at {s[pos:]}")
            num, ident, sym = m.groups()
            if num is not None:
                tokens.append(('NUM', int(num)))
            elif ident is not None:
                tokens.append(('ID', ident))
            else:
                tokens.append(('SYM', sym))
            pos = m.end()
        tokens.append(('EOF', None))
        return tokens

    # AST Node types:
    # ('NUM', val)
    # ('CELL', name)
    # ('UNARY', '-', expr)
    # ('BIN', op, left, right)
    # ('FUNC', name, args) where arg is ('RANGE', c1, c2) or expr
    # ('IF', op, left, right, then_expr, else_expr)

    def parse_formula(s: str):
        tokens = tokenize(s)
        idx = 0

        def peek():
            return tokens[idx]

        def consume(expected_type=None, expected_val=None):
            nonlocal idx
            t = tokens[idx]
            if expected_type and t[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {t}")
            if expected_val and t[1] != expected_val:
                raise ValueError(f"Expected {expected_val}, got {t}")
            idx += 1
            return t

        def parse_expr():
            node = parse_term()
            while peek()[0] == 'SYM' and peek()[1] in ('+', '-'):
                op = consume()[1]
                right = parse_term()
                node = ('BIN', op, node, right)
            return node

        def parse_term():
            node = parse_unary()
            while peek()[0] == 'SYM' and peek()[1] in ('*', '/'):
                op = consume()[1]
                right = parse_unary()
                node = ('BIN', op, node, right)
            return node

        def parse_unary():
            if peek()[0] == 'SYM' and peek()[1] == '-':
                consume()
                return ('UNARY', '-', parse_unary())
            return parse_atom()

        def parse_atom():
            t_type, t_val = peek()
            if t_type == 'NUM':
                consume()
                return ('NUM', t_val)
            elif t_type == 'SYM' and t_val == '(':
                consume()
                node = parse_expr()
                consume('SYM', ')')
                return node
            elif t_type == 'ID':
                consume()
                if peek()[0] == 'SYM' and peek()[1] == '(':
                    consume('SYM', '(')
                    if t_val == 'IF':
                        left = parse_expr()
                        op_tok = consume('SYM')
                        op = op_tok[1]
                        right = parse_expr()
                        consume('SYM', ',')
                        then_expr = parse_expr()
                        consume('SYM', ',')
                        else_expr = parse_expr()
                        consume('SYM', ')')
                        return ('IF', op, left, right, then_expr, else_expr)
                    else:
                        args = []
                        while True:
                            # Check if range: ID followed by ':'
                            if peek()[0] == 'ID' and tokens[idx + 1][0] == 'SYM' and tokens[idx + 1][1] == ':':
                                c1 = consume('ID')[1]
                                consume('SYM', ':')
                                c2 = consume('ID')[1]
                                args.append(('RANGE', c1, c2))
                            else:
                                args.append(parse_expr())
                            if peek()[0] == 'SYM' and peek()[1] == ',':
                                consume('SYM', ',')
                            else:
                                break
                        consume('SYM', ')')
                        return ('FUNC', t_val, args)
                else:
                    return ('CELL', t_val)
            else:
                raise ValueError(f"Unexpected token {peek()}")

        ast = parse_expr()
        return ast

    def expand_range(c1: str, c2: str):
        col1, row1 = ord(c1[0]), int(c1[1:])
        col2, row2 = ord(c2[0]), int(c2[1:])
        if col1 > col2:
            col1, col2 = col2, col1
        if row1 > row2:
            row1, row2 = row2, row1
        res = []
        for r in range(row1, row2 + 1):
            r_str = str(r)
            for c in range(col1, col2 + 1):
                name = chr(c) + r_str
                if name in cells:
                    res.append(name)
        return res

    parsed_cells = {}
    state = {}  # 0: unvisited, 1: visiting, 2: visited
    results = {}

    for name, content in cells.items():
        s = content.strip()
        if s.startswith('='):
            parsed_cells[name] = parse_formula(s[1:])
            state[name] = 0
        else:
            results[name] = int(s)
            state[name] = 2

    def eval_cell(name: str) -> int | str:
        if name not in cells:
            return 0
        st = state[name]
        if st == 2:
            return results[name]
        if st == 1:
            return "#CYCLE!"
        state[name] = 1
        val = eval_ast(parsed_cells[name])
        results[name] = val
        state[name] = 2
        return val

    def eval_ast(node) -> int | str:
        ntype = node[0]
        if ntype == 'NUM':
            return node[1]
        elif ntype == 'CELL':
            return eval_cell(node[1])
        elif ntype == 'UNARY':
            val = eval_ast(node[2])
            if isinstance(val, str):
                return val
            return -val
        elif ntype == 'BIN':
            op, left_node, right_node = node[1], node[2], node[3]
            lval = eval_ast(left_node)
            if isinstance(lval, str):
                return lval
            rval = eval_ast(right_node)
            if isinstance(rval, str):
                return rval
            if op == '+':
                return lval + rval
            elif op == '-':
                return lval - rval
            elif op == '*':
                return lval * rval
            elif op == '/':
                if rval == 0:
                    return "#DIV/0!"
                if (lval < 0) ^ (rval < 0):
                    return -(abs(lval) // abs(rval))
                else:
                    return abs(lval) // abs(rval)
        elif ntype == 'IF':
            _, op, left_node, right_node, then_node, else_node = node
            lval = eval_ast(left_node)
            if isinstance(lval, str):
                return lval
            rval = eval_ast(right_node)
            if isinstance(rval, str):
                return rval
            if op == '=':
                cond = (lval == rval)
            elif op == '<>':
                cond = (lval != rval)
            elif op == '<':
                cond = (lval < rval)
            elif op == '<=':
                cond = (lval <= rval)
            elif op == '>':
                cond = (lval > rval)
            elif op == '>=':
                cond = (lval >= rval)
            else:
                raise ValueError(f"Unknown operator {op}")
            return eval_ast(then_node if cond else else_node)
        elif ntype == 'FUNC':
            _, fname, args = node
            vals = []
            for arg in args:
                if arg[0] == 'RANGE':
                    for cname in expand_range(arg[1], arg[2]):
                        v = eval_cell(cname)
                        if isinstance(v, str):
                            return v
                        vals.append(v)
                else:
                    v = eval_ast(arg)
                    if isinstance(v, str):
                        return v
                    vals.append(v)
            if not vals:
                return 0
            if fname == 'SUM':
                return sum(vals)
            elif fname == 'MIN':
                return min(vals)
            elif fname == 'MAX':
                return max(vals)
            else:
                raise ValueError(f"Unknown function {fname}")

    for name in cells:
        if state[name] == 0:
            eval_cell(name)

    return {name: results[name] for name in cells}
